using System.Collections.Generic;public class Solution{public int[] TopKFrequent(int[]a,int k){var m=new Dictionary<int,int>();foreach(int x in a)m[x]=m.GetValueOrDefault(x)+1;var b=new List<int>[a.Length+1];foreach(var e in m){b[e.Value]??=new();b[e.Value].Add(e.Key);}int[]o=new int[k];int p=0;for(int i=b.Length-1;i>=0&&p<k;i--)if(b[i]!=null)foreach(int x in b[i]){o[p++]=x;if(p==k)break;}return o;}}
